161	#[inline]
162	fn parse_field(p: &mut GraphqlParser) -> ParsedSyntax {
163	    if !is_at_field(p) {
164	        return Absent;
165	    }
166	    let m = p.start();
167	    // This is currently the only time we need to lookahead
168	    // so there is no need to implement NthToken to use nth_at
169	    let next_token = p.lookahead();
170	
171	    // alias is optional, so if there is a colon, we parse it as an alias
172	    // otherwise we parse it as a normal field name
173	    if next_token == T![:] {
174	        let m = p.start();
175	
176	        // name is checked for in `is_at_field`
177	        parse_name(p).ok();
178	        p.bump(T![:]);
179	        m.complete(p, GRAPHQL_ALIAS);
180	
181	        parse_name(p).or_add_diagnostic(p, expected_name);
182	    } else {
183	        // name is checked for in `is_at_field`
184	        parse_name(p).ok();
185	    }
186	
187	    // arguments are optional
188	    parse_arguments(p).ok();
189	    DirectiveList.parse_list(p);
190	
191	    if is_at_selection_set(p) {
192	        parse_selection_set(p).ok();
193	    }
194	    Present(m.complete(p, GRAPHQL_FIELD))
195	}
