108	#[inline]
109	fn parse_root_operation_type_definition(p: &mut GraphqlParser) -> ParsedSyntax {
110	    if !(is_at_root_operation_type_definition(p)) {
111	        return Absent;
112	    }
113	    let m = p.start();
114	    if p.at_ts(OPERATION_TYPE) {
115	        let m = p.start();
116	        p.bump_ts(OPERATION_TYPE);
117	        m.complete(p, GRAPHQL_OPERATION_TYPE);
118	    }
119	    // missing operation type
120	    else if p.at(T![:]) {
121	        p.error(expected_operation_type(p, p.cur_range()));
122	    }
123	    // handle typo in operation type
124	    else {
125	        p.error(expected_operation_type(p, p.cur_range()));
126	        p.bump_any();
127	    }
128	    p.expect(T![:]);
129	    parse_named_type(p).or_add_diagnostic(p, expected_named_type);
130	
131	    Present(m.complete(p, GRAPHQL_ROOT_OPERATION_TYPE_DEFINITION))
132	}
