151	/// To prevent a missing closing brace from causing the parser to include the next definition
152	/// as part of the root operation type definition
153	/// ```graphql
154	/// schema {
155	///    query: Query
156	///    mutation: Mutation
157	///
158	/// schema {
159	///   query: Query
160	/// }
161	#[inline]
162	fn is_at_root_operation_type_definition_end(p: &mut GraphqlParser<'_>) -> bool {
163	    // stop at closing brace or at the start of a new definition
164	    p.at(T!['}'])
165	        || (!p.at_ts(OPERATION_TYPE) && is_at_definition(p))
166	        // start of a new operation definition
167	        || (p.at_ts(OPERATION_TYPE) && !p.nth_at(1, T![:]))
168	}
