134	fn is_at_root_operation_type_definition_end(p: &mut GraphqlParser<'_>) -> bool {
135	    // stop at closing brace or at the start of a new definition
136	    p.at(T!['}'])
137	        || (!p.at_ts(OPERATION_TYPE) && is_at_definition(p))
138	        // start of a new operation definition
139	        || (p.at_ts(OPERATION_TYPE) && !p.lookahead_at(T![:]))
140	}
