diff --git a/tmp/cur_token_source.rs b/tmp/cur_token_source.rs
new file mode 100644
index 000000000..441ab7356
--- /dev/null
+++ b/tmp/cur_token_source.rs
@@ -0,0 +1,150 @@
+use crate::lexer::GraphqlLexer;
+use biome_graphql_syntax::GraphqlSyntaxKind::{EOF, TOMBSTONE};
+use biome_graphql_syntax::{GraphqlSyntaxKind, TextRange};
+use biome_parser::diagnostic::ParseDiagnostic;
+use biome_parser::lexer::Lexer;
+use biome_parser::prelude::TokenSource;
+use biome_parser::token_source::Trivia;
+use biome_rowan::TriviaPieceKind;
+
+pub(crate) struct GraphqlTokenSource<'source> {
+    lexer: GraphqlLexer<'source>,
+    trivia: Vec<Trivia>,
+    current: NonTriviaToken,
+    next: Option<NonTriviaToken>,
+}
+
+struct NonTriviaToken {
+    kind: GraphqlSyntaxKind,
+    range: TextRange,
+    preceding_line_break: bool,
+}
+
+impl Default for NonTriviaToken {
+    fn default() -> Self {
+        Self {
+            kind: TOMBSTONE,
+            range: TextRange::default(),
+            preceding_line_break: false,
+        }
+    }
+}
+
+impl<'source> GraphqlTokenSource<'source> {
+    pub fn from_str(source: &'source str) -> Self {
+        let lexer = GraphqlLexer::from_str(source);
+
+        let mut source = Self {
+            lexer,
+            trivia: Vec::new(),
+            current: NonTriviaToken::default(),
+            next: None,
+        };
+
+        source.advance_to_next_non_trivia_token(true);
+        source
+    }
+
+    fn advance_to_next_non_trivia_token(&mut self, first_token: bool) {
+        self.current = match self.next.take() {
+            Some(next) => next,
+            None => self.next_non_trivia_token(first_token),
+        }
+    }
+
+    pub fn lookahead(&mut self) -> GraphqlSyntaxKind {
+        match self.next.as_ref() {
+            Some(next) => next.kind,
+            None if self.current.kind != EOF => {
+                let next_token = self.next_non_trivia_token(false);
+                let next_kind = next_token.kind;
+                self.next = Some(next_token);
+                next_kind
+            }
+            None => EOF,
+        }
+    }
+
+    // We mostly look ahead by one token
+    // so there is no need to implement NthToken to use nth_at
+    pub fn lookahead_at(&mut self, kind: GraphqlSyntaxKind) -> bool {
+        self.lookahead() == kind
+    }
+
+    #[must_use]
+    fn next_non_trivia_token(&mut self, first_token: bool) -> NonTriviaToken {
+        let mut non_trivia_token = NonTriviaToken::default();
+
+        let mut trailing = !first_token;
+
+        loop {
+            let kind = self.lexer.next_token(());
+            let trivia_kind = TriviaPieceKind::try_from(kind);
+
+            match trivia_kind {
+                Err(_) => {
+                    // Not trivia
+                    non_trivia_token.kind = kind;
+                    non_trivia_token.range = self.lexer.current_range();
+                    break;
+                }
+                Ok(trivia_kind) => {
+                    if trivia_kind.is_newline() {
+                        trailing = false;
+                        non_trivia_token.preceding_line_break = true;
+                    }
+
+                    self.trivia.push(Trivia::new(
+                        trivia_kind,
+                        self.lexer.current_range(),
+                        trailing,
+                    ));
+                }
+            }
+        }
+
+        non_trivia_token
+    }
+}
+
+impl<'source> TokenSource for GraphqlTokenSource<'source> {
+    type Kind = GraphqlSyntaxKind;
+
+    fn current(&self) -> Self::Kind {
+        self.current.kind
+    }
+
+    fn current_range(&self) -> TextRange {
+        self.current.range
+    }
+
+    fn text(&self) -> &str {
+        self.lexer.source()
+    }
+
+    fn has_preceding_line_break(&self) -> bool {
+        self.current.preceding_line_break
+    }
+
+    fn bump(&mut self) {
+        if self.current.kind != EOF {
+            self.advance_to_next_non_trivia_token(false)
+        }
+    }
+
+    fn skip_as_trivia(&mut self) {
+        if self.current() != EOF {
+            self.trivia.push(Trivia::new(
+                TriviaPieceKind::Skipped,
+                self.current_range(),
+                false,
+            ));
+
+            self.advance_to_next_non_trivia_token(false)
+        }
+    }
+
+    fn finish(self) -> (Vec<Trivia>, Vec<ParseDiagnostic>) {
+        (self.trivia, self.lexer.finish())
+    }
+}
diff --git a/tmp/cur_value.rs b/tmp/cur_value.rs
new file mode 100644
index 000000000..8685d13ae
--- /dev/null
+++ b/tmp/cur_value.rs
@@ -0,0 +1,295 @@
+/// Parse all inpul value
+/// https://spec.graphql.org/October2021/#sec-Input-Values
+use crate::parser::{parse_name, GraphqlParser};
+use biome_graphql_syntax::{
+    GraphqlSyntaxKind::{self, *},
+    T,
+};
+use biome_parser::{
+    parse_lists::ParseNodeList, parse_recovery::ParseRecovery, parsed_syntax::ParsedSyntax,
+    prelude::ParsedSyntax::*, token_set, Parser, TokenSet,
+};
+
+use super::{
+    argument::is_at_argument_list_end,
+    is_at_name,
+    parse_error::{expected_object_field, expected_value},
+    variable::{is_at_variable, parse_variable},
+};
+
+const BOOLEAN_VALUE_SET: TokenSet<GraphqlSyntaxKind> = token_set![TRUE_KW, FALSE_KW];
+
+struct ListValueElementListParseRecovery;
+
+impl ParseRecovery for ListValueElementListParseRecovery {
+    type Kind = GraphqlSyntaxKind;
+    type Parser<'source> = GraphqlParser<'source>;
+    const RECOVERED_KIND: Self::Kind = GRAPHQL_BOGUS_VALUE;
+
+    fn is_at_recovered(&self, p: &mut Self::Parser<'_>) -> bool {
+        is_at_value(p) || is_at_list_end(p)
+    }
+}
+
+#[derive(Default)]
+struct ListValueElementList;
+
+impl ParseNodeList for ListValueElementList {
+    type Kind = GraphqlSyntaxKind;
+    type Parser<'source> = GraphqlParser<'source>;
+
+    const LIST_KIND: Self::Kind = GRAPHQL_LIST_VALUE_ELEMENT_LIST;
+
+    fn parse_element(&mut self, p: &mut Self::Parser<'_>) -> ParsedSyntax {
+        parse_value(p)
+    }
+
+    fn is_at_list_end(&self, p: &mut Self::Parser<'_>) -> bool {
+        is_at_list_end(p)
+    }
+
+    fn recover(
+        &mut self,
+        p: &mut Self::Parser<'_>,
+        parsed_element: ParsedSyntax,
+    ) -> biome_parser::parse_recovery::RecoveryResult {
+        parsed_element.or_recover(p, &ListValueElementListParseRecovery, expected_value)
+    }
+}
+
+struct ObjectValueMemberListParseRecovery;
+
+impl ParseRecovery for ObjectValueMemberListParseRecovery {
+    type Kind = GraphqlSyntaxKind;
+    type Parser<'source> = GraphqlParser<'source>;
+    const RECOVERED_KIND: Self::Kind = GRAPHQL_OBJECT_FIELD;
+
+    fn is_at_recovered(&self, p: &mut Self::Parser<'_>) -> bool {
+        is_at_name(p) || is_at_object_end(p)
+    }
+}
+
+#[derive(Default)]
+struct ObjectValueMemberList;
+
+impl ParseNodeList for ObjectValueMemberList {
+    type Kind = GraphqlSyntaxKind;
+    type Parser<'source> = GraphqlParser<'source>;
+
+    const LIST_KIND: Self::Kind = GRAPHQL_OBJECT_VALUE_MEMBER_LIST;
+
+    fn parse_element(&mut self, p: &mut Self::Parser<'_>) -> ParsedSyntax {
+        parse_object_field(p)
+    }
+
+    fn is_at_list_end(&self, p: &mut Self::Parser<'_>) -> bool {
+        is_at_object_end(p)
+    }
+
+    fn recover(
+        &mut self,
+        p: &mut Self::Parser<'_>,
+        parsed_element: ParsedSyntax,
+    ) -> biome_parser::parse_recovery::RecoveryResult {
+        parsed_element.or_recover(
+            p,
+            &ObjectValueMemberListParseRecovery,
+            expected_object_field,
+        )
+    }
+}
+
+#[inline]
+pub(crate) fn parse_value(p: &mut GraphqlParser) -> ParsedSyntax {
+    if is_at_variable(p) {
+        parse_variable(p)
+    } else if is_at_int(p) {
+        parse_int(p)
+    } else if is_at_float(p) {
+        parse_float(p)
+    } else if is_at_string(p) {
+        parse_string(p)
+    } else if is_at_boolean(p) {
+        parse_boolean(p)
+    } else if is_at_null(p) {
+        parse_null(p)
+    } else if is_at_enum(p) {
+        parse_enum(p)
+    } else if is_at_list(p) {
+        parse_list(p)
+    } else if is_at_object(p) {
+        parse_object(p)
+    } else {
+        return Absent;
+    }
+}
+
+#[inline]
+fn parse_int(p: &mut GraphqlParser) -> ParsedSyntax {
+    if !is_at_int(p) {
+        return Absent;
+    }
+    let m = p.start();
+    p.bump(GRAPHQL_INT_LITERAL);
+    Present(m.complete(p, GRAPHQL_INT_VALUE))
+}
+
+#[inline]
+fn parse_float(p: &mut GraphqlParser) -> ParsedSyntax {
+    if !is_at_float(p) {
+        return Absent;
+    }
+    let m = p.start();
+    p.bump(GRAPHQL_FLOAT_LITERAL);
+    Present(m.complete(p, GRAPHQL_FLOAT_VALUE))
+}
+
+#[inline]
+pub(crate) fn parse_string(p: &mut GraphqlParser) -> ParsedSyntax {
+    if !is_at_string(p) {
+        return Absent;
+    }
+    let m = p.start();
+    p.bump(GRAPHQL_STRING_LITERAL);
+    Present(m.complete(p, GRAPHQL_STRING_VALUE))
+}
+
+#[inline]
+fn parse_boolean(p: &mut GraphqlParser) -> ParsedSyntax {
+    if !is_at_boolean(p) {
+        return Absent;
+    }
+    let m = p.start();
+    p.bump_ts(BOOLEAN_VALUE_SET);
+    Present(m.complete(p, GRAPHQL_BOOLEAN_VALUE))
+}
+
+#[inline]
+fn parse_null(p: &mut GraphqlParser) -> ParsedSyntax {
+    if !is_at_null(p) {
+        return Absent;
+    }
+    let m = p.start();
+    p.bump(T![null]);
+    Present(m.complete(p, GRAPHQL_NULL_VALUE))
+}
+
+#[inline]
+fn parse_enum(p: &mut GraphqlParser) -> ParsedSyntax {
+    if !is_at_enum(p) {
+        return Absent;
+    }
+    let m = p.start();
+    parse_name(p).ok();
+    Present(m.complete(p, GRAPHQL_ENUM_VALUE))
+}
+
+#[inline]
+fn parse_list(p: &mut GraphqlParser) -> ParsedSyntax {
+    if !is_at_list(p) {
+        return Absent;
+    }
+    let m = p.start();
+    p.bump(T!['[']);
+    ListValueElementList.parse_list(p);
+    p.expect(T![']']);
+    Present(m.complete(p, GRAPHQL_LIST_VALUE))
+}
+
+#[inline]
+fn parse_object(p: &mut GraphqlParser) -> ParsedSyntax {
+    if !is_at_object(p) {
+        return Absent;
+    }
+    let m = p.start();
+    p.bump(T!['{']);
+    ObjectValueMemberList.parse_list(p);
+    p.expect(T!['}']);
+    Present(m.complete(p, GRAPHQL_OBJECT_VALUE))
+}
+
+#[inline]
+fn parse_object_field(p: &mut GraphqlParser) -> ParsedSyntax {
+    if !is_at_object_field(p) {
+        return Absent;
+    }
+    let m = p.start();
+    parse_name(p).ok();
+    p.expect(T![:]);
+    parse_value(p).or_add_diagnostic(p, expected_value);
+    Present(m.complete(p, GRAPHQL_OBJECT_FIELD))
+}
+
+#[inline]
+fn is_at_value(p: &GraphqlParser) -> bool {
+    is_at_variable(p)
+        || is_at_int(p)
+        || is_at_float(p)
+        || is_at_string(p)
+        || is_at_boolean(p)
+        || is_at_null(p)
+        || is_at_enum(p)
+        || is_at_list(p)
+        || is_at_object(p)
+}
+
+#[inline]
+fn is_at_int(p: &GraphqlParser) -> bool {
+    p.at(GRAPHQL_INT_LITERAL)
+}
+
+#[inline]
+fn is_at_float(p: &GraphqlParser) -> bool {
+    p.at(GRAPHQL_FLOAT_LITERAL)
+}
+
+#[inline]
+pub(crate) fn is_at_string(p: &GraphqlParser) -> bool {
+    p.at(GRAPHQL_STRING_LITERAL)
+}
+
+#[inline]
+fn is_at_boolean(p: &GraphqlParser) -> bool {
+    p.at_ts(BOOLEAN_VALUE_SET)
+}
+
+#[inline]
+fn is_at_null(p: &GraphqlParser) -> bool {
+    p.at(T![null])
+}
+
+#[inline]
+fn is_at_enum(p: &GraphqlParser) -> bool {
+    is_at_name(p)
+}
+
+#[inline]
+fn is_at_list(p: &GraphqlParser) -> bool {
+    p.at(T!['['])
+}
+
+#[inline]
+fn is_at_list_end(p: &mut GraphqlParser) -> bool {
+    p.at(T![']'])
+    // at next argument
+    || p.lookahead() == T![:]
+    // value is only used in argument
+    || is_at_argument_list_end(p)
+}
+
+#[inline]
+fn is_at_object(p: &GraphqlParser) -> bool {
+    p.at(T!['{'])
+}
+
+#[inline]
+fn is_at_object_field(p: &GraphqlParser) -> bool {
+    is_at_name(p)
+}
+
+#[inline]
+fn is_at_object_end(p: &mut GraphqlParser) -> bool {
+    p.at(T!['}'])
+    // value is only used in argument
+    || is_at_argument_list_end(p)
+}
